html, body {
  overflow: hidden;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
}

#renderCanvas {
  width: 100%;
  height: 100%;
  touch-action: none;
}

// outside createScene()
window.addEventListener('resize', function () {
  engine.resize();
});

const canvas = document.getElementById('renderCanvas');
const engine = new BABYLON.Engine(canvas);

const createScene = function () {
  const scene = new BABYLON.Scene(engine);
  scene.createDefaultCameraOrLight(true, false, true);

  // The fun stuff

  return scene;
};

const scene = createScene();

engine.runRenderLoop(function () {
  scene.render();
});

window.addEventListener('resize', function () {
  engine.resize();
});

const sphere = BABYLON.MeshBuilder.CreateSphere(
  'mySphere',
  { segments: 50, diameter: 0.3, diameterY: 0.4 },
  scene
);

const box = BABYLON.MeshBuilder.CreateBox('myBox', {
  width: 2,
  height: 0.05,
  depth: 0.5,
  faceColors: [
    new BABYLON.Color4(1, 0.2, 0.5, 1),
    new BABYLON.Color4(0.2, 0.1, 0.3, 1),
    new BABYLON.Color4(0.5, 0, 1, 1)
  ]
});

const ground = BABYLON.MeshBuilder.CreateGround('myGround', {
  width: 3,
  height: 3,
  subdivisions: 30
});
ground.material = new BABYLON.StandardMaterial();
ground.material.wireframe = true; // show the grid

const terrain = BABYLON.MeshBuilder.CreateGroundFromHeightMap(
  'myTerrain',
  'images/heightmap.png',
  { width: 3, height: 3, subdivisions: 100, maxHeight: 0.5 }
);

const createScene = async function () {
  const scene = new BABYLON.Scene(engine);
  scene.createDefaultCameraOrLight(true, false, true);

  const fontData = await (await fetch('fonts/GreatVibes.json')).json();

  const text = BABYLON.MeshBuilder.CreateText(
    'myText', 'Hello Babylon!', fontData,
    { size: 0.5, depth: 0.05, resolution: 32 },
    scene
  );

  return scene;
};

createScene().then(function (scene) {
  engine.runRenderLoop(function () {
    scene.render();
  });
});

// scene.createDefaultCameraOrLight(true, false, true);
scene.createDefaultLight();

const camera = new BABYLON.UniversalCamera(
  'uCamera',
  new BABYLON.Vector3(0, 1, -5),
  scene
);
camera.attachControl();                    // enable input
camera.inputs.addMouseWheel();             // wheel moves too
camera.setTarget(BABYLON.Vector3.Zero());  // look at the center

const camera = new BABYLON.ArcRotateCamera(
  'arCamera', 0, 0, 10, BABYLON.Vector3.Zero(), scene
);
camera.attachControl();
camera.setPosition(new BABYLON.Vector3(0, 0, -10));

camera.lowerBetaLimit = Math.PI / 4;
camera.upperBetaLimit = Math.PI / 2;

camera.lowerAlphaLimit = Math.PI / 4;
camera.upperAlphaLimit = Math.PI / 2;

camera.lowerRadiusLimit = 8;
camera.upperRadiusLimit = 15;

const sphere = BABYLON.MeshBuilder.CreateSphere('', { diameter: 0.5 });
const sphereMaterial = new BABYLON.StandardMaterial();
sphere.material = sphereMaterial;

sphereMaterial.ambientColor = new BABYLON.Color3(0, 1, 1);
scene.ambientColor = new BABYLON.Color3(0, 0.5, 0.5);

sphereMaterial.emissiveColor = new BABYLON.Color3(0.5, 0, 0.5);
sphereMaterial.alpha = 0.5;       // 1 = solid
sphereMaterial.wireframe = true;

sphereMaterial.diffuseTexture = new BABYLON.Texture('images/earth.jpg');

// shows even without light:
// sphereMaterial.emissiveTexture = new BABYLON.Texture('images/earth.jpg');

const box = BABYLON.MeshBuilder.CreateBox('', {
  size: 0.3,
  faceUV: [
    new BABYLON.Vector4(0, 0, 1 / 6, 1),
    new BABYLON.Vector4(1 / 6, 0, 2 / 6, 1),
    new BABYLON.Vector4(2 / 6, 0, 3 / 6, 1),
    new BABYLON.Vector4(3 / 6, 0, 4 / 6, 1),
    new BABYLON.Vector4(4 / 6, 0, 5 / 6, 1),
    new BABYLON.Vector4(5 / 6, 0, 1, 1)
  ],
  wrap: true
});
const boxMaterial = new BABYLON.StandardMaterial();
boxMaterial.emissiveTexture = new BABYLON.Texture('images/faces.png');
box.material = boxMaterial;

box.position.x = 1;
box.position = new BABYLON.Vector3(-0.5, 0.2, 0.1);

box.rotation.z = Math.PI / 3;
box.rotation = new BABYLON.Vector3(0, 0, Math.PI / 3);

box.scaling.x = 2;
box.scaling = new BABYLON.Vector3(2, 0.8, 2.5);

const utilLayer = new BABYLON.UtilityLayerRenderer(scene);
const positionGizmo = new BABYLON.PositionGizmo(utilLayer);
positionGizmo.attachedMesh = box;

const rotationGizmo = new BABYLON.RotationGizmo(utilLayer);
rotationGizmo.attachedMesh = box;

const scaleGizmo = new BABYLON.ScaleGizmo(utilLayer);
scaleGizmo.attachedMesh = box;

const planeGizmo = new BABYLON.PlaneRotationGizmo(
  new BABYLON.Vector3(0, 1, 0),  // axis
  new BABYLON.Color3(1, 0, 0),   // color
  utilLayer
);
planeGizmo.attachedMesh = box;

scene.registerBeforeRender(function () {
  box.rotation.x += 0.01;
  box.rotation.y += 0.01;
  box.rotation.z += 0.01;
});

const animation = new BABYLON.Animation(
  'yRotAnimation', 'rotation.y', 30,
  BABYLON.Animation.ANIMATIONTYPE_FLOAT,
  BABYLON.Animation.ANIMATIONLOOPMODE_CYCLE
);

animation.setKeys([
  { frame: 0, value: 0 },
  { frame: 60, value: Math.PI * 2 }
]);

box.animations = [];
box.animations.push(animation);

scene.beginAnimation(box, 0, 60, true); // target, from, to, loop

const light = new BABYLON.PointLight(
  'pointLight', new BABYLON.Vector3(0, 1, 0), scene
);

const utilLayer = new BABYLON.UtilityLayerRenderer(scene);
const lightGizmo = new BABYLON.LightGizmo(utilLayer);
lightGizmo.light = light;

const light = new BABYLON.SpotLight(
  'spotlight',
  new BABYLON.Vector3(0, 1, 0),   // position
  new BABYLON.Vector3(0, -1, 0),  // direction
  Math.PI / 3,                    // cone angle
  2,                              // decay
  scene
);
light.range = 10;

const light = new BABYLON.DirectionalLight(
  'directionalLight', new BABYLON.Vector3(-2, -3, 0), scene
);
light.intensity = 0.5;

const light = new BABYLON.HemisphericLight(
  'hemisphericLight', new BABYLON.Vector3(-5, 2, 0), scene
);
light.groundColor = new BABYLON.Color3(0, 1, 0);
light.diffuse = new BABYLON.Color3(0, 0, 1);
light.specular = new BABYLON.Color3(0, 1, 0);

const sphere = BABYLON.MeshBuilder.CreateSphere(
  'shadowCaster', { diameter: 0.3 }
);
sphere.position = new BABYLON.Vector3(1, 1.5, 0);

const light = new BABYLON.DirectionalLight(
  'directionalLight', new BABYLON.Vector3(-2, -3, 0), scene
);

const shadowGenerator = new BABYLON.ShadowGenerator(1024, light);
shadowGenerator.addShadowCaster(sphere);
ground.receiveShadows = true;

shadowGenerator.setDarkness(0.8);
shadowGenerator.useBlurExponentialShadowMap = true;
shadowGenerator.useKernelBlur = true;
shadowGenerator.blurKernel = 64;

scene.fogMode = BABYLON.Scene.FOGMODE_LINEAR;
scene.fogStart = 10;
scene.fogEnd = 50;

scene.onPointerDown = function castRay() {
  const hit = scene.pick(scene.pointerX, scene.pointerY);
};

scene.onPointerDown = function castRay() {
  const hit = scene.pick(scene.pointerX, scene.pointerY);

  if (hit.pickedMesh && hit.pickedMesh.name === 'shadowCaster') {
    hit.pickedMesh.material = new BABYLON.StandardMaterial();
    hit.pickedMesh.material.diffuseColor = BABYLON.Color3.Random();
  }
};

BABYLON.SceneLoader.ImportMesh(
  null, 'models/', 'Fox.gltf', scene,
  function (meshes, particleSystems, skeletons, animationGroups) {
    const model = meshes[0];
    model.scaling = new BABYLON.Vector3(0.5, 0.5, 0.5);
    shadowGenerator.addShadowCaster(model);
  }
);

// inside the callback
animationGroups[0].stop();
animationGroups[5].play(true); // true = loop

BABYLON.SceneLoader.ImportMeshAsync(null, 'models/', 'Fox.gltf', scene)
  .then((result) => {
    const model = result.meshes[0];
    model.scaling = new BABYLON.Vector3(0.5, 0.5, 0.5);
    result.animationGroups[3].play(true);
  });

const bgMusic = new BABYLON.Sound(
  'backgroundMusic',
  'audio/piano.wav',
  scene,
  null,
  { autoplay: true, loop: true }
);

bgMusic.play();
bgMusic.pause();
bgMusic.stop();

// 1) index.html: add this script after babylon.js
// <script src='https://cdn.babylonjs.com/inspector/babylon.inspector.bundle.js'></script>

// 2) main.js: add this at the end of your script
scene.debugLayer.show();
